import math

def check_condition(n):
    """Checks if for all k coprime to n, k^2 = 1 (mod n)."""
    if n < 2:
        return False

    # Check k from 1 up to n-1, as this covers all residue classes
    for k in range(1, n):
        if math.gcd(k, n) == 1:
            # Check k^2 = 1 (mod n)
            if (k * k - 1) % n != 0:
                return False
    return True

results = {}
for n in range(2, 21):
    results[n] = check_condition(n)

print("N | Condition Met?")
print("-" * 20)
for n, passed in results.items():
    status = "Yes" if passed else "No"
    print(f"{n:2} | {status}")

print("\nAll results:")
print({n: "Yes" if passed else "No" for n, passed in results.items()})
